import React from 'react';
import Card from '@mui/material/Card';
import CardActions from '@mui/material/CardActions';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import IconButton from '@mui/material/IconButton';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import MoreVertIcon from '@mui/icons-material/MoreVert';

const Card_Form = ({ClickView}) => {
  const [anchorEl, setAnchorEl] = React.useState(null);
  const open = Boolean(anchorEl);
  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  return (
    <Card sx={{ width:200, maxHeight:230 }} style={{display:'flex',justifyContent:"center",flexDirection:'column',alignItems:'center',paddingTop:'20px'}}>
        <CardMedia
        // style={{backgroundColor:'ButtonHighlight'}}
        sx={{ height: 100,width:100 }}
        image={require('../../images/form.png')}
        title="green iguana"
      />
      <CardContent style={{width:'100%'}}>
      <Typography style={{fontWeight:'600',fontSize:20}}>Form1</Typography>
     
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-end',width:'100%',}}>
      <Typography style={{fontWeight:'300',fontSize:18,color:'blue',paddingLeft:'80px',cursor:'pointer'}} onClick={ClickView}>View</Typography>
      <IconButton
        aria-label="more"
        id="long-button"
        // aria-controls={open ? 'long-menu' : undefined}
        // aria-expanded={open ? 'true' : undefined}
        // aria-haspopup="true"
        onClick={handleClick}
      >
        <MoreVertIcon />
      </IconButton>
      <Menu
        id="long-menu"
        MenuListProps={{
          'aria-labelledby': 'long-button',
        }}
        anchorEl={anchorEl}
        open={open}
        onClose={handleClose}
       
      >
        {/* {options.map((option) => ( */}
          <MenuItem onClick={handleClose}  >
          Rename
          </MenuItem>
          <MenuItem onClick={handleClose}  >
          Delete
          </MenuItem>
        {/* ))} */}
      </Menu>
      </div>
      </CardContent>  
    </Card>
  )
}

export default Card_Form;
