import React from 'react'
import Box from '@mui/material/Box';
import Tab from '@mui/material/Tab';
import TabContext from '@mui/lab/TabContext';
import TabList from '@mui/lab/TabList';
import TabPanel from '@mui/lab/TabPanel';
import './style.css';
import FormCreation from '../DragandDrop/Form_Creation';
import Reg_User from '../RegisterdUser/Reg_User';
import Form_Settings from '../FormSettings/Form_Settings';

const ViewForms = () => {
    const [value, setValue] = React.useState('1');

    const handleChange = (event, newValue) => {
      setValue(newValue);
    };

const renderTabContent=(tabvalue)=>{
    console.log("selected tab",tabvalue);
    switch(tabvalue){
        case '1':
            return (<FormCreation/>)
        case '2':
            return ( <Reg_User/>)
        case '3':
            return (<Form_Settings/>)
        default:
            return null;
    }

}
  return (
    <Box sx={{ width: '100%', typography: 'body1'}} >
      <TabContext value={value}>
        <Box sx={{ borderBottom: 1, borderColor: 'divider',display:'flex',justifyContent:"center"}}>
          <TabList onChange={handleChange} aria-label="lab API tabs example">
            <Tab label="Form" value="1" />
            <Tab label="Registration" value="2" />
            <Tab label="Settings" value="3" />
          </TabList>
        </Box>
      {renderTabContent(value)}
      </TabContext>
    </Box>

  )
}

export default ViewForms
